                    "es-ES": "Si la posición inicial del proyectil y su dirección son relativas al jugador o al mundo.",
                    "es-MX": "Si la posición y dirección iniciales del proyectil son relativas al jugador o el mundo.",
                    "fr-FR": "Indique si la position et la direction de départ du projectile sont relatives au joueur ou à la joueuse ou à l’environnement.",
                    "it-IT": "Determina se la posizione iniziale e la direzione del proiettile sono relative all'utente o al mondo.",
                    "ja-JP": "投射物の開始位置と方向が、プレイヤーと環境のどちらを基準にするか",
                    "ko-KR": "투사체의 시작 위치나 방향이 플레이어와 세계 중 어디가 판단 대상인지 여부입니다.",
                    "pl-PL": "Określa czy pozycja startowa pocisku i jego kierunek są ustalane względem gracza czy świata gry.",
                    "pt-BR": "Define se a posição inicial e a direção do projétil são relativas ao jogador ou ao mundo.",
