            {
                "name": "homingStrength",
                "type": "float",
                "default": 1,
                "min": 0,
                "max": 1,
                "description": {
                    "en-US": "A 0 to 1 value representing how strongly the projectile will follow its target and how easily it will lose its target. At 0 the projectile won't follow its target at all at 1 it will follow its target aggressively and never lose it.",
                    "de-DE": "Ein Wert zwischen 0 und 1 der vorgibt wie sehr das Projektil seinem Ziel folgt und wie leicht es sein Ziel verliert. Bei 0 folgt es seinem Ziel überhaupt nicht bei 1 verfolgt es das Ziel aggressiv und dauerhaft.",
                    "es-ES": "Valor de 0 a 1 que representa la intensidad con la que el proyectil seguirá a su objetivo y la facilidad con la que lo perderá. En 0 el proyectil no seguirá al objetivo en absoluto; en 1 seguirá al objetivo de forma agresiva y no lo perderá.",
                    "es-MX": "Un valor de 0 a 1 que representa hasta qué punto seguirá el proyectil a su objetivo y la facilidad con la que lo perderá. En 0 el proyectil no seguirá a su objetivo en absoluto. En 1 seguirá a su objetivo de forma activa y nunca lo perderá.",
                    "fr-FR": "Une valeur de 0 à 1 représentant la capacité du projectile de suivre sa cible. À 0 le projectile ne suivra pas du tout sa cible à 1 il suivra sa cible de manière agressive et ne la perdra jamais.",
                    "it-IT": "Un valore da 0 a 1 indica con quanta forza il proiettile seguirà il bersaglio e quanto facilmente lo perderà. A 0 il proiettile non seguirà minimamente il bersaglio mentre a 1 lo seguirà inesorabilmente senza mai perderlo.",
                    "ja-JP": "0から1の範囲で投射物が標的を追尾する精度を変更する。0では投射物は標的をまったく追尾せず、1ではしつこく標的を追尾して決して見失わない",
                    "ko-KR": "투사체가 대상을 얼마나 쉽게 따라갈 0에서 1까지의 범위입니다. 0이면 투사체는 대상을 따라가지 않고 1이면 능동적이게 따라가며 절대로 대상을 놓치지 않습니다.",
                    "pl-PL": "Wartość od 0 do 1 określająca jak bardzo pocisk będzie podążał za swoim celem i jak łatwo go zgubi. Przy 0 pocisk nie będzie w ogóle podążał za celem a przy 1 będzie podążał za celem agresywnie i nigdy go nie zgubi.",
                    "pt-BR": "Um valor de 0 a 1 que representa a perseverança do projétil perseguindo um alvo e a facilidade com que ele o perde. Se for 0 o projétil não seguirá o alvo e se for 1 ele seguirá de forma agressiva e nunca o perderá.",
                    "ru-RU": "Значение в диапазоне от 0 до 1 определяющее эффективность следования снаряда за целью. При выборе значения 0 снаряд вовсе не будет следовать за целью. При выборе значения 1 снаряд будет следовать за целью постоянно и не утратит самонаведение.",
                    "th-TH": "ค่า 0 ถึง 1 แสดงถึงความเสถียรของโพรเจกไทล์ว่าจะติดตามเป้าหมายหรือหลุดจากเป้าหมายได้ง่ายเพียงใด ที่ค่า 0 โพรเจกไทล์จะไม่ติดตามเป้าหมายเลย ส่วนที่ค่า 1 คือจะติดตามเป้าหมายอย่างดุเดือดและไม่หลุดจากเป้าหมายเลย",
                    "tr-TR": "Atılır cismin hedefi nasıl takip edeceğini ve hedefinden nasıl şaşacağını temsil eden 0 ila 1 değeri. 0'da atılır cisim hedefini takip etmez; 1'de ise devamlı takip eder ve hedefinden şaşmaz.",
                    "zh-CN": "此数值范围为0到1，表示该弹道追踪目标的强度，以及跟丢目标的难易度。0表示弹道完全不会追踪目标，1表示弹道会积极追踪目标且绝不会跟丢。",
                    "zh-TW": "0到1的數值表示拋射物追蹤目標以及追丟目標的程度。數值為0時，此拋射物完全不會追蹤目標。若為1時，則會永遠跟隨目標直到擊中。"
                }
            }
